#!/bin/sh set -e ME=$(basename "$0") entrypoint\_log() { if \[ -z "${NGINX\_ENTRYPOINT\_QUIET\_LOGS:-}" \]; then echo "$@" fi } add\_stream\_block() { local conffile="/etc/nginx/nginx.conf" if grep -q -E "\\s\*stream\\s\*\\{" "$conffile"; then entrypoint\_log "$ME: $conffile contains a stream block; include $stream\_output\_dir/\*.conf to enable stream templates" else # check if the file can be modified, e.g. not on a r/o filesystem touch "$conffile" 2>/dev/null || { entrypoint\_log "$ME: info: can not modify $conffile (read-only file system?)"; exit 0; } entrypoint\_log "$ME: Appending stream block to $conffile to include $stream\_output\_dir/\*.conf" cat << END >> "$conffile" # added by "$ME" on "$(date)" stream { include $stream\_output\_dir/\*.conf; } END fi } auto\_envsubst() { local template\_dir="${NGINX\_ENVSUBST\_TEMPLATE\_DIR:-/etc/nginx/templates}" local suffix="${NGINX\_ENVSUBST\_TEMPLATE\_SUFFIX:-.template}" local output\_dir="${NGINX\_ENVSUBST\_OUTPUT\_DIR:-/etc/nginx/conf.d}" local stream\_suffix="${NGINX\_ENVSUBST\_STREAM\_TEMPLATE\_SUFFIX:-.stream-template}" local stream\_output\_dir="${NGINX\_ENVSUBST\_STREAM\_OUTPUT\_DIR:-/etc/nginx/stream-conf.d}" local filter="${NGINX\_ENVSUBST\_FILTER:-}" local template defined\_envs relative\_path output\_path subdir defined\_envs=$(printf '${%s} ' $(awk -v filter="$filter" 'END { for (name in ENVIRON) { print ( name ~ filter ) ? name : "" } }' < /dev/null)) \[ -d "$template\_dir" \] || return 0 if \[ ! -w "$output\_dir" \]; then entrypoint\_log "$ME: ERROR: $template\_dir exists, but $output\_dir is not writable" return 0 fi find "$template\_dir" -follow -type f -name "\*$suffix" -print | while read -r template; do relative\_path="${template#"$template\_dir/"}" output\_path="$output\_dir/${relative\_path%"$suffix"}" subdir=$(dirname "$relative\_path") # create a subdirectory where the template file exists mkdir -p "$output\_dir/$subdir" entrypoint\_log "$ME: Running envsubst on $template to $output\_path" envsubst "$defined\_envs" < "$template" > "$output\_path" done # Print the first file with the stream suffix, this will be false if there are none if test -n "$(find "$template\_dir" -name "\*$stream\_suffix" -print -quit)"; then mkdir -p "$stream\_output\_dir" if \[ ! -w "$stream\_output\_dir" \]; then entrypoint\_log "$ME: ERROR: $template\_dir exists, but $stream\_output\_dir is not writable" return 0 fi add\_stream\_block find "$template\_dir" -follow -type f -name "\*$stream\_suffix" -print | while read -r template; do relative\_path="${template#"$template\_dir/"}" output\_path="$stream\_output\_dir/${relative\_path%"$stream\_suffix"}" subdir=$(dirname "$relative\_path") # create a subdirectory where the template file exists mkdir -p "$stream\_output\_dir/$subdir" entrypoint\_log "$ME: Running envsubst on $template to $output\_path" envsubst "$defined\_envs" < "$template" > "$output\_path" done fi } auto\_envsubst exit 0

